if(!plans[savedPlan]) savedPlan=null;
function setMood(next){mood=next;const m=moods[mood];$('#cover-image').style.backgroundImage=`url('/assets/${m.image}')`;$('#cover-title').innerHTML=word(m.title);$('#cover-description').textContent=word(m.description);$$('[data-mood]', $('.mood-switch')).forEach(b=>{b.classList.toggle('active',b.dataset.mood===next);b.setAttribute('aria-pressed',String(b.dataset.mood===next))})}
function renderStories(){const matches=stories.filter(s=>filter==='all'||s.category===filter);const visible=expanded||filter!=='all'?matches:matches.slice(0,3);$('#story-grid').classList.toggle('expanded',expanded);$('#story-grid').innerHTML=visible.map((s,i)=>`<article class="story-card ${i===0?'featured':''}"><div class="story-image"><button class="story-open" data-story="${s.id}" aria-label="${word(s.title)}"><img src="/assets/${s.image}" alt="${word(s.title)}" loading="lazy"></button><button class="bookmark ${saved.includes(s.id)?'is-saved':''}" data-save="${s.id}" aria-label="${saved.includes(s.id)?t('Remove from notebook','Quitar del cuaderno'):t('Save to notebook','Guardar en el cuaderno')}" aria-pressed="${saved.includes(s.id)}">${icon('bookmark')}</button></div><div class="story-copy"><span class="story-category">${word(s.tag)}</span><button class="story-open" data-story="${s.id}"><h3>${word(s.title)}</h3></button><p>${word(s.description)}</p><span class="story-meta">${s.time} ${t('MIN READ','MIN DE LECTURA')}</span></div></article>`).join('');$('#story-total').textContent=`${matches.length} ${t('stories to linger over','historias para leer sin prisa')}`;$('#all-stories').hidden=expanded||filter!=='all';$$('.filter').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))})}
function openDialog(id){const d=$('#'+id);if(!d.open)d.showModal()}
function openStory(id){currentStory=id;const s=stories.find(s=>s.id===id);if(!s)return;$('#reader-content').innerHTML=`<img class="reader-cover" src="/assets/${s.image}" alt="${word(s.title)}"><article class="reader-body"><span class="eyebrow">${word(s.tag)}</span><h2>${word(s.title)}</h2><div class="reader-meta">EL SANCTUARIO · ${s.time} ${t('MIN READ','MIN DE LECTURA')} · ${t('EDITORIAL PREVIEW','MUESTRA EDITORIAL')}</div>${s.body[lang]}<a class="reader-source" href="${s.source}" target="_blank" rel="noopener">${t('Explore the official hotel page','Explorar la página oficial del hotel')}</a><div class="reader-actions"><button class="pill dark" data-save="${s.id}">${saved.includes(id)?t('Remove from my notebook','Quitar de mi cuaderno'):t('Keep this story','Guardar esta historia')}</button><button class="text-link" data-plan-from-story="${id}">${t('Make it part of my stay','Incluirlo en mi estancia')}</button></div></article>`;$('#reader-save').dataset.save=id;$('#reader-save').classList.toggle('is-saved',saved.includes(id));$('#reader-save').setAttribute('aria-pressed',String(saved.includes(id)));openDialog('reader');$('#reader').scrollTop=0}
function toggleSave(id){if(!stories.some(s=>s.id===id))return;const had=saved.includes(id);saved=had?saved.filter(s=>s!==id):[...saved,id];const stored=writeStore('sanctuario-saved',saved);updateCounts();renderStories();if($('#notebook').open)renderNotebook();if($('#reader').open&&currentStory===id){const top=$('#reader').scrollTop;openStory(id);$('#reader').scrollTop=top}toast(stored?(had?t('Removed from your notebook.','Se quitó de tu cuaderno.'):t('A little memory, saved in your notebook.','Un pequeño recuerdo, guardado en tu cuaderno.')):t('Saved for this visit. This browser cannot keep it after you leave.','Guardado durante esta visita. Este navegador no permite conservarlo después.'))}
function updateCounts(){$$('.saved-count').forEach(x=>x.textContent=saved.length+(savedPlan?1:0))}
function renderNotebook(){const items=saved.map(id=>stories.find(s=>s.id===id));$('#notebook-content').innerHTML=items.map(s=>`<div class="notebook-item"><img src="/assets/${s.image}" alt=""><button data-notebook-story="${s.id}"><small>${word(s.tag)}</small>${word(s.title)}</button><button class="icon-button" data-save="${s.id}" aria-label="${t('Remove','Quitar')}">${icon('close')}</button></div>`).join('')+(savedPlan?`<div class="saved-plan"><span class="eyebrow">${t('MY NEXT STAY','MI PRÓXIMA ESTANCIA')}</span><h3>${word(plans[savedPlan].label)}</h3><p>${plans[savedPlan].moments.map(m=>word(m.title)).join(' · ')}</p><button class="text-link" id="book-saved-plan">${t('Share my wishes with the hotel','Compartir mis deseos con el hotel')}</button><button class="icon-button" id="remove-plan" aria-label="${t('Remove saved moments','Quitar momentos guardados')}">${icon('close')}</button></div>`:'');if(!items.length&&!savedPlan)$('#notebook-content').innerHTML=`<div class="empty-notebook">${icon('bookmark')}<h3>${t('A place for your favourites.','Un lugar para tus favoritos.')}</h3><p>${t('Save a story with the bookmark icon, or keep the moments you would love on your next stay.','Guarda una historia con el marcador o los momentos que te gustaría vivir en tu próxima estancia.')}</p><button class="text-link" data-close="notebook">${t('Start exploring','Empezar a explorar')}</button></div>`}
function renderPlan(){$('#itinerary').innerHTML=plans[feeling].moments.map(m=>`<article class="moment"><img src="/assets/${m.image}" alt="${word(m.title)}" loading="lazy"><span class="small-label">${word(m.time)}</span><h3>${word(m.title)}</h3><p>${word(m.text)}</p></article>`).join('');$$('[data-feeling]').forEach(b=>{b.classList.toggle('active',b.dataset.feeling===feeling);b.setAttribute('aria-pressed',String(b.dataset.feeling===feeling))})}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600)}
const events={guitar:{start:'2027-03-06',end:'2027-03-14',name:'XXIII Zihuatanejo International Guitar Festival',url:'https://www.zihuafest.com/'},sail:{start:'2027-02-14',end:'2027-02-28',name:'Por Los Niños Sailfest Zihuatanejo',url:'https://www.zihuatanejo-sailfest.com/copy-of-home-1'}};
const localDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function datePlus(day,days){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
function openBooking(eventKey=null,extra=''){const ev=events[eventKey];$('#booking-context').textContent=ev?ev.name:t('Tell us when you would love to be here.','Cuéntanos cuándo te gustaría estar aquí.');$('#arrival').value=ev?ev.start:datePlus(localDate(),7);$('#departure').value=ev?ev.end:datePlus($('#arrival').value,3);$('#arrival').min=localDate();$('#departure').min=datePlus($('#arrival').value,1);$('#stay-notes').value=extra||(ev?t('I would like to plan a stay around ','Me gustaría planear una estancia durante ')+ev.name:'');$('#booking-result').textContent='';openDialog('booking')}
function downloadCalendar(key){const ev=events[key];const date=s=>s.replaceAll('-','');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const text=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//El Sanctuario//Journal//EN\r\nCALSCALE:GREGORIAN\r\nBEGIN:VEVENT\r\nUID:${key}-2027@el-sanctuario-revista.osteineur.chatgpt.site\r\nDTSTAMP:${stamp}\r\nDTSTART;VALUE=DATE:${date(ev.start)}\r\nDTEND;VALUE=DATE:${date(ev.end)}\r\nSUMMARY:${ev.name}\r\nLOCATION:Zihuatanejo - Guerrero - Mexico\r\nDESCRIPTION:Confirm current program with the organizer. ${ev.url}\r\nURL:${ev.url}\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`el-sanctuario-${key}-2027.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Your calendar file is ready.','Tu archivo de calendario está listo.'))}
function renderSearch(){const q=$('#search-input').value.trim().toLocaleLowerCase(lang);const matches=stories.filter(s=>(' '+word(s.title)+' '+word(s.description)+' '+word(s.tag)+' '+(s.category==='taste'?'gastronomy gastronomía chef cocina food':'' )+' '+(s.id==='spa'?'spa clarins wellness bienestar':'')).toLocaleLowerCase(lang).replace(/[^\p{L}\p{N}]+/gu,' ').includes(' '+q));$('#search-results').innerHTML=matches.length?matches.map(s=>`<button class="search-result" data-search-story="${s.id}"><img src="/assets/${s.image}" alt=""><span><small>${word(s.tag)}</small>${word(s.title)}</span></button>`).join(''):`<p class="caption">${t('No stories found. Try “spa”, “chef” or “villa”.','No encontramos historias. Prueba “spa”, “chef” o “villa”.')}</p>`}
function weatherDescription(code){if(code===0)return t('Clear skies over the coast','Cielo despejado en la costa');if(code<=3)return t('Clouds drifting over the bay','Nubes sobre la bahía');if(code<=48)return t('A softer coastal sky','Un cielo costero más suave');if(code<=67||code>=80&&code<=82)return t('Rain along the coast','Lluvia en la costa');if(code>=95)return t('Thunderstorms in the area','Tormentas en la zona');return t('The coast, in its own rhythm','La costa, a su propio ritmo')}
function renderWeather(){if(!weather)return;const c=weather.current,d=weather.daily;$('.weather-top use').setAttribute('href',c.weather_code===0?'#i-sun':c.weather_code<=48?'#i-cloud':'#i-rain');$('#weather-temp').innerHTML=`${Math.round(c.temperature_2m)}<span>°</span>`;$('#weather-description').textContent=weatherDescription(c.weather_code);$('#weather-sunset').textContent=d.sunset[0].slice(11,16);$('#weather-wind').textContent=Math.round(c.wind_speed_10m)+' km/h';$('#weather-feels').textContent=Math.round(c.apparent_temperature)+'°C';$('#weather-updated').textContent=t('Updated ','Actualizado ')+c.time.slice(11,16)+' · °C';$('#forecast').innerHTML=d.time.slice(1,5).map((day,i)=>`<div class="forecast-day"><span>${new Intl.DateTimeFormat(lang==='en'?'en-US':'es-MX',{weekday:'short',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'))}</span><strong>${Math.round(d.temperature_2m_max[i+1])}° / ${Math.round(d.temperature_2m_min[i+1])}°</strong></div>`).join('')}
let weatherFailed=false;
async function loadWeather(){try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=17.64&longitude=-101.55&current=temperature_2m,apparent_temperature,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,sunset&timezone=America%2FMexico_City&forecast_days=5',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('unavailable');const data=await r.json();if(!Number.isFinite(data.current?.temperature_2m)||!data.daily?.sunset?.length)throw Error('invalid data');weather=data;weatherFailed=false;renderWeather()}catch{weatherFailed=true;$('#weather-description').textContent=t('Weather temporarily unavailable','Clima temporalmente no disponible');$('#weather-updated').textContent=t('Live conditions could not be loaded.','No se pudieron cargar los datos actuales.')}}
function updateClock(){$('#bay-time').textContent=new Intl.DateTimeFormat(lang==='en'?'en-US':'es-MX',{timeZone:'America/Mexico_City',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' · Zihuatanejo'}
function setLanguage(){document.documentElement.lang=lang;$$('[data-en]').forEach(el=>el.innerHTML=el.dataset[lang]);$$('[data-placeholder-en]').forEach(el=>el.placeholder=el.dataset[lang==='en'?'placeholderEn':'placeholderEs']);$('#language').innerHTML=lang==='en'?'EN <span>/ ES</span>':'ES <span>/ EN</span>';$('#language').setAttribute('aria-label',lang==='en'?'Cambiar a español':'Switch to English');document.title=t('El Sanctuario — A living journal by La Casa Que Canta','El Sanctuario — Una revista viva de La Casa Que Canta');renderStories();renderPlan();setMood(mood);updateClock();renderWeather();if(weatherFailed){$('#weather-description').textContent=t('Weather temporarily unavailable','Clima temporalmente no disponible');$('#weather-updated').textContent=t('Live conditions could not be loaded.','No se pudieron cargar los datos actuales.')}if($('#reader').open)openStory(currentStory);if($('#notebook').open)renderNotebook();if($('#search-dialog').open)renderSearch()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.close){$('#'+b.dataset.close).close();return}
 if(b.dataset.save){toggleSave(b.dataset.save);return}
 if(b.dataset.story){openStory(b.dataset.story);return}
 if(b.dataset.mood){setMood(b.dataset.mood);return}
 if(b.dataset.filter){filter=b.dataset.filter;renderStories();return}
 if(b.dataset.feeling){feeling=b.dataset.feeling;renderPlan();return}
 if(b.classList.contains('saved-trigger')){renderNotebook();openDialog('notebook');return}
 if(b.classList.contains('booking-trigger')){openBooking();return}
 if(b.dataset.event){openBooking(b.dataset.event);return}
 if(b.dataset.calendar){downloadCalendar(b.dataset.calendar);return}
 if(b.dataset.notebookStory){$('#notebook').close();openStory(b.dataset.notebookStory);return}
 if(b.dataset.searchStory){$('#search-dialog').close();openStory(b.dataset.searchStory);return}
 if(b.dataset.planFromStory){const s=stories.find(x=>x.id===b.dataset.planFromStory);$('#reader').close();openBooking(null,t('I was inspired by: ','Me inspiró: ')+word(s.title));return}
 if(b.id==='book-saved-plan'){$('#notebook').close();openBooking(null,t('I would love these moments: ','Me encantaría vivir estos momentos: ')+plans[savedPlan].moments.map(m=>word(m.title)).join(' '));return}
 if(b.id==='remove-plan'){savedPlan=null;writeStore('sanctuario-plan',null);updateCounts();renderNotebook();return}
});
$('#language').addEventListener('click',()=>{lang=lang==='en'?'es':'en';writeStore('sanctuario-language',lang);setLanguage()});
$('#all-stories').addEventListener('click',()=>{expanded=true;renderStories()});
$('#save-itinerary').addEventListener('click',()=>{savedPlan=feeling;const ok=writeStore('sanctuario-plan',feeling);updateCounts();toast(ok?t('Your next chapter is in your notebook.','Tu próximo capítulo está en tu cuaderno.'):t('Kept for this visit. Browser storage is unavailable.','Guardado durante esta visita. No hay almacenamiento disponible.'))});
$('#search-trigger').addEventListener('click',()=>{renderSearch();openDialog('search-dialog');$('#search-input').focus()});
$('#search-input').addEventListener('input',renderSearch);
$('#newsletter-form').addEventListener('submit',e=>{e.preventDefault();const interests=$$('input[name="interest"]:checked').map(i=>i.value);if(!interests.length){$('#newsletter-result').textContent=t('Choose at least one interest.','Elige al menos un interés.');return}writeStore('sanctuario-interests',interests);$('#newsletter-result').textContent=t('Your preview preferences are saved on this device. You have not been subscribed; email delivery will be connected for launch.','Tus preferencias de muestra se guardaron en este dispositivo. No se creó una suscripción; los envíos se conectarán para el lanzamiento.');$('#newsletter-email').value=''});
$('#arrival').addEventListener('change',()=>{const min=datePlus($('#arrival').value,1);$('#departure').min=min;if($('#departure').value<min)$('#departure').value=datePlus($('#arrival').value,3)});
$('#booking-form').addEventListener('submit',e=>{e.preventDefault();const arrival=$('#arrival').value,departure=$('#departure').value;if(departure<=arrival){$('#booking-result').textContent=t('Departure must be after arrival.','La salida debe ser posterior a la llegada.');return}const subject=t('My next stay — ','Mi próxima estancia — ')+$('#property').value;const body=t('Hello La Casa Que Canta team,\n\nI would like to ask about a stay.\n','Hola, equipo de La Casa Que Canta:\n\nMe gustaría consultar una estancia.\n')+'\n'+t('Property: ','Propiedad: ')+$('#property').value+'\n'+t('Arrival: ','Llegada: ')+arrival+'\n'+t('Departure: ','Salida: ')+departure+'\n\n'+$('#stay-notes').value+'\n\n'+t('Please let me know availability and rates. Thank you!','¿Me pueden compartir disponibilidad y tarifas? ¡Gracias!');const href='mailto:sales.reservations@lacasaquecanta.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);window.location.href=href;$('#booking-result').textContent=t('Your email app should open with a draft. Send it to the hotel to request availability; this does not confirm a reservation.','Tu aplicación de correo debería abrir un borrador. Envíalo al hotel para consultar disponibilidad; esto no confirma una reservación.')});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#install-trigger').addEventListener('click',()=>openDialog('install-dialog'));
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install-app').hidden=false});
$('#install-app').addEventListener('click',async()=>{if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$('#install-app').hidden=true});
const hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'America/Mexico_City',hour:'2-digit',hour12:false}).format(new Date()));
mood=hour>=6&&hour<16?'morning':hour>=16&&hour<19?'golden':'evening';
const preferences=readStore('sanctuario-interests',null);if(Array.isArray(preferences))$$('input[name="interest"]').forEach(i=>i.checked=preferences.includes(i.value));
setLanguage();updateCounts();loadWeather();setInterval(updateClock,30000);setInterval(loadWeather,15*60*1000);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
